INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(9301, '2 Kings 12:13', '2 Kings', 12, 13, '&nbsp;د سپينو زرو پيالو، جامونو، بيګلو، د ډيوو سرپوښونه، يا د سرو زرو يا سپينو زرو نورو سامانونو دپاره څۀ پېسې هم نۀ وې استعمال شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9302, '2 Kings 12:14', '2 Kings', 12, 14, '&nbsp;دا پېسې مزدورانو له ورکولے شوې او د مرمت سامان ورباندې اخستلے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9303, '2 Kings 12:15', '2 Kings', 12, 15, '&nbsp;ذمه وارو سړو په صداقت سره کار کولو، نو د پېسو د حِساب کِتاب ضرورت نۀ پېښېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9304, '2 Kings 12:16', '2 Kings', 12, 16, '&nbsp;خو د ګناه د تاوان د نذرانو او د ګناه د نذرانو دپاره ورکړے شوې پېسې د مالِک خُدائ په کور کښې نۀ استعمالېدې، دا د اِمامانو وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9305, '2 Kings 12:17', '2 Kings', 12, 17, '&nbsp;په هغه وخت د شام بادشاه حِزائيل د جات په ښار باندې حمله وکړه او هغه يې فتح کړو، بيا هغۀ په يروشلم باندې د حملې کولو فېصله وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9306, '2 Kings 12:18', '2 Kings', 12, 18, '&nbsp;د يهوداه بادشاه يوآس هغه ټولې نذرانې واخستلې چې د هغۀ پلار نيکۀ يهوسفط، يهورام او اخزياه مالِک خُدائ ته وقف کړې وې او د دې سره يې خپلې نذرانې او د مالِک خُدائ کور او د محل د خزانو ټول سرۀ زر يې هم ورسره يو ځائ کړل او دا هر څۀ يې حِزائيل بادشاه له په تُحفه کښې ولېږل، نو خزائيل بادشاه بيا خپل فوج د يروشلم نه واپس بوتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9307, '2 Kings 12:19', '2 Kings', 12, 19, '&nbsp;يوآس بادشاه چې نور هر څۀ هم کړى دى هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9308, '2 Kings 13:1', '2 Kings', 13, 1, '&nbsp;د يهوداه بادشاه اخزياه زوئ يوآس د بادشاهۍ په درويشتم کال، د ياهُو زوئ يهوآخز د اِسرائيل بادشاه شو او هغۀ په سامريه کښې اوولس کاله بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9309, '2 Kings 13:2', '2 Kings', 13, 2, '&nbsp;هغۀ د يربعام بادشاه په شان د مالِک خُدائ خِلاف ګناه وکړه چا چې اِسرائيليان د ګناه طرف ته بوتلى وُو، هغۀ هيڅکله خپل بد عملونه نۀ پرېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9310, '2 Kings 13:3', '2 Kings', 13, 3, '&nbsp;نو مالِک خُدائ اِسرائيل ته غصه شو او هغۀ د شام بادشاه حِزائيل او د هغۀ زوئ بِن‌حدد پرېښودل چې اِسرائيل له بار بار شکست ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9311, '2 Kings 13:4', '2 Kings', 13, 4, '&nbsp;نو يهوآخز مالِک خُدائ ته سوال وکړو نو مالِک خُدائ د هغۀ سوال واورېدو، ځکه چې مالِک خُدائ ته پته وه چې د شام بادشاه د اِسرائيل سره څومره سخت ظلم کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9312, '2 Kings 13:5', '2 Kings', 13, 5, '&nbsp;نو مالِک خُدائ اِسرائيلو له يو خلاصونکے راولېږلو، چې هغوئ يې د شاميانو نه آزاد کړل، نو اِسرائيلو د مخکښې په شان په امن کښې ژوند تېرولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9313, '2 Kings 13:6', '2 Kings', 13, 6, '&nbsp;خو هغوئ بيا هم هغه ګناهونه پرې نۀ ښودل چې يربعام بادشاه اِسرائيليان هغې طرف ته بوتلى وُو او د اشيرې بُت ستنه په سامريه کښې پاتې شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9314, '2 Kings 13:7', '2 Kings', 13, 7, '&nbsp;د يهوآخز سره صرف پنځوس په آسونو سوارۀ کسان، او لس جنګى ګاډۍ او لس زره پياده فوجيان پاتې وُو، ځکه چې د شام بادشاه د هغوئ نه علاوه نور ټول لښکر تباه کړى وُو او سم غوبل يې ورباندې کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9315, '2 Kings 13:8', '2 Kings', 13, 8, '&nbsp;يهوآخز چې نور هر څۀ هم کړى وُو سره د هغۀ د ټولو بهادرۍ کارونو، هر څۀ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9316, '2 Kings 13:9', '2 Kings', 13, 9, '&nbsp;هغه مړ شو او په سامريه کښې ښخ شو او د هغۀ زوئ يهوآس د هغۀ نه پس بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9317, '2 Kings 13:10', '2 Kings', 13, 10, '&nbsp;د يهوداه بادشاه يوآس د بادشاهۍ په اووۀ دېرشم کال، د يهوآخز زوئ يهوآس د اِسرائيل بادشاه شو او هغۀ په سامريه کښې شپاړس کاله حکومت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9318, '2 Kings 13:11', '2 Kings', 13, 11, '&nbsp;هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه او يربعام د نباط زوئ د بدو لارو نه نۀ اوړېدو، چا چې اِسرائيليان د ګناه طرف ته بوتلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9319, '2 Kings 13:12', '2 Kings', 13, 12, '&nbsp;نور هر څۀ چې يهوآس کړى وُو، سره د يهوداه بادشاه امصياه خِلاف په جنګ کښې د هغۀ بهادرى، هغه د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9320, '2 Kings 13:13', '2 Kings', 13, 13, '&nbsp;يهوآس مړ شو او د سامريه په شاهى اديره کښې ښخ شو او د هغۀ زوئ بادشاه شو چې د هغۀ نوم هم يربعام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9321, '2 Kings 13:14', '2 Kings', 13, 14, '&nbsp;اليشع پېغمبر په يوه سخته بيمارۍ بيمار شو او چې هغه مړ کېدو نو د اِسرائيل بادشاه يهوآس مِلاوېدو له ورَغلو او د هغۀ د حالت په ليدو باندې يې ژړل. هغۀ چغې وهلې، ”زما پلاره، زما پلاره. تۀ د اِسرائيلو تکړه حِفاظت کوونکے وې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9322, '2 Kings 13:15', '2 Kings', 13, 15, '&nbsp;اليشع حُکم ورکړو، ”لينده او يو څو غشى واخله.“ نو يهوآس واخستل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9323, '2 Kings 13:16', '2 Kings', 13, 16, '&nbsp;او اليشع هغۀ ته وفرمائيل چې، ”د غشو ويشتلو دپاره تيار شه.“ نو بادشاه هم هغه شان وکړل او اليشع خپل لاسونه د بادشاه په لاسونو کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9324, '2 Kings 13:17', '2 Kings', 13, 17, '&nbsp;نو د پېغمبر په خبرو يې عمل وکړو، بادشاه هغه کړکۍ کولاو کړه چې د شام طرف ته وه. اليشع ورته وفرمائيل، ”غشے ووله.“ څنګه چې بادشاه غشے وويشتو، نو پېغمبر وفرمائيل، ”تۀ د مالِک خُدائ غشے يې، په کوم باندې چې به شام فتح کړى. تۀ به په افيق کښې د شاميانو سره تر هغې پورې جنګ کوې چې شکست ورکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9325, '2 Kings 13:18', '2 Kings', 13, 18, '&nbsp;بيا اليشع بادشاه ته وفرمائيل چې، ”نور غشى واخله او د دې سره زمکه ووهه.“ نو بادشاه درې ځلې زمکه ووهله او بيا يې بس کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9326, '2 Kings 13:19', '2 Kings', 13, 19, '&nbsp;په دې باندې اليشع غصه شو او بادشاه ته يې وفرمائيل، ”تا له په کار وُو چې پينځۀ شپږ ځلې دې وهلے، نو تا به په شاميانو باندې پوره فتح موندلے وے، خو اوس به تۀ هغوئ له صِرف درې ځل شکست ورکړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9327, '2 Kings 13:20', '2 Kings', 13, 20, '&nbsp;اليشع مړ شو او ښخ شو. هر کال به د سپرلى په موسم کښې د موآبيانو لښکر د اِسرائيل په مُلک حمله کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9328, '2 Kings 13:21', '2 Kings', 13, 21, '&nbsp;يو وخت د يو سړى په جنازه کښې، ډاکوان وليدلے شو او دې خلقو د اليشع په قبر باندې مړے وروغورزولو او وتښتېدل. نو چې څنګه لاش د اليشع د هډوکى سره ولګېدو، نو هغه کس راژوندے شو او ودرېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9329, '2 Kings 13:22', '2 Kings', 13, 22, '&nbsp;د يهوآخز په ټوله بادشاهۍ کښې د شام بادشاه حِزائيل به په اِسرائيلو زياتے کولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9330, '2 Kings 13:23', '2 Kings', 13, 23, '&nbsp;خو مالِک خُدائ په هغوئ مهربان او رحم کوونکے وو. او هغوئ يې دې ته نۀ پرېښودل چې تباه شى، خو د هغه لوظ په وجه يې د هغوئ مدد کولو، چې کوم يې د اِبراهيم، اِسحاق او يعقوب سره کړے وو. هغۀ هيڅکله خپل خلق نۀ هېرول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9331, '2 Kings 13:24', '2 Kings', 13, 24, '&nbsp;کله چې د شام بادشاه حِزائيل مړ شو نو د هغۀ زوئ بِن‌حدد بادشاه شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9332, '2 Kings 13:25', '2 Kings', 13, 25, '&nbsp;بيا د اِسرائيل بادشاه يهوآس بِن‌حدد له درې ځله شکست ورکړو او هغه ښارونه يې بيا قبضه کړل چې د يهوآخز د بادشاهۍ په دوران کښې بِن‌حدد نيولى وُو، يهوآخز د يهوآس پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9333, '2 Kings 14:1', '2 Kings', 14, 1, '&nbsp;د اِسرائيل بادشاه د يهوآخز زوئ يهوآس د بادشاهۍ په دوېم کال، د يوآس زوئ امصياه د يهوداه بادشاه شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9334, '2 Kings 14:2', '2 Kings', 14, 2, '&nbsp;چې عُمر يې پينځويشت کاله وو او هغۀ په يروشلم کښې نهۀ‌ويشت کاله بادشاهى وکړه. د هغۀ مور يهوعدان د يروشلم وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9335, '2 Kings 14:3', '2 Kings', 14, 3, '&nbsp;هغۀ هم هغه کار کولو چې مالِک خُدائ پرې رضا کېدو، خو د خپل پلار نيکۀ داؤد په شان نۀ وو، او هغه کارونه يې کول چې څۀ د هغۀ پلار يوآس کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9336, '2 Kings 14:4', '2 Kings', 14, 4, '&nbsp;هغۀ علاقائى عبادتخانې راونۀ غورزولې او خلقو هلته بيا هم قربانۍ او سوزېدونکې خوشبوئى سوزوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9337, '2 Kings 14:5', '2 Kings', 14, 5, '&nbsp;څنګه چې امصياه ته د بادشاهۍ ټول اختيار مِلاو شو، نو هغۀ هغه آفسران قتل کړل چې د هغۀ پلار يعنې بادشاه يې وژلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9338, '2 Kings 14:6', '2 Kings', 14, 6, '&nbsp;خو هغۀ د هغوئ بچى ونۀ وژل او په هغه څۀ يې عمل وکړو چې مالِک خُدائ د موسىٰ په شريعت کښې فرمائيلى وُو، ”مور او پلار دې د بچو د جرمونو په وجه نۀ شى وژلے او د مور پلار د جرمونو په وجه دې د هغوئ بچى نۀ شى وژلے، يو کس دې صِرف د خپل جرم په وجه ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9339, '2 Kings 14:7', '2 Kings', 14, 7, '&nbsp;امصياه لس زره ادومى فوجيان د مالګې په مېدان کښې ووژل، هغۀ په يو جنګ کښې د سلع ښار قبضه کړو او په دې باندې يې يقتى‌اېل نوم کېښودو چې تر اوسه پورې يې هم دا نوم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9340, '2 Kings 14:8', '2 Kings', 14, 8, '&nbsp;بيا امصياه د اِسرائيل بادشاه يهوآس له پېغام وړُونکى ولېږل او ورته يې ووئيل چې جنګ ته راوړاندې شه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9341, '2 Kings 14:9', '2 Kings', 14, 9, '&nbsp;خو يهوآس واپس دا جواب ورولېږلو، ”يو ځل د لبنان په غرونو کښې د ازغو بوټى د دِيار ونې له دا پېغام ولېږلو چې، زما زوئ له ستا لور ورکړه چې وادۀ يې کړى. يو ځنګلى ځناور هلته تېرېدو او د ازغو په بوټى يې پښې کېښودې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9342, '2 Kings 14:10', '2 Kings', 14, 10, '&nbsp;نو امصياه، تا ادوميانو له شکست ورکړے دے او مغروره شوے يې. خو په خپل شُهرت باندې ګزاره کوه او په کور کښې کښېنه. داسې بلا ولې راخبروې چې په تا او ستا په خلقو باندې تباهى راولى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9343, '2 Kings 14:11', '2 Kings', 14, 11, '&nbsp;خو امصياه ورته غوږ نۀ نيولو، نو يهوآس بادشاه د خپلو سړو سره روان شو او په يهوداه کښې يې د بيت‌شمس سره د هغۀ خِلاف جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9344, '2 Kings 14:12', '2 Kings', 14, 12, '&nbsp;د امصياه لښکر شکست وخوړو او د هغۀ ټول فوجيان خپلو کورونو ته وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9345, '2 Kings 14:13', '2 Kings', 14, 13, '&nbsp;يهوآس امصياه ونيولو، يروشلم ته وړاندې لاړو او د اِفرائيم د دروازې نه واخله د ګوټ دروازې پورې دېوال يې راغورزولو چې تقريباً دوه سوه ګزه فاصله وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
