(9389, '2 Kings 15:28', '2 Kings', 15, 28, '&nbsp;هغۀ د مالِک خُدائ په نظر کښې بدى وکړه او د نباط زوئ يربعام په بدو مِثالونو يې عمل وکړو، چا چې په اِسرائيل کښې ګناه کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9390, '2 Kings 15:29', '2 Kings', 15, 29, '&nbsp;د فقح د بادشاهۍ په دوران کښې د اسور بادشاه تغلت فلاسر د عيون، ابيل‌بيت‌معکه، ينوحاه، قادِس، حصور او جِلعاد ښارونه، او د ګليل او نفتالى علاقې قبضه کړې او خلق يې اسور ته قېديان بوتلل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9391, '2 Kings 15:30', '2 Kings', 15, 30, '&nbsp;د يهوداه بادشاه د عُزياه زوئ يوتام د بادشاهۍ په شلم کال، د ايله زوئ هوسيع د فقح بادشاه خِلاف منصوبه جوړه کړه، هغه يې ووژلو او د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9392, '2 Kings 15:31', '2 Kings', 15, 31, '&nbsp;نور هر څۀ چې فقح کړى وُو هغه د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9393, '2 Kings 15:32', '2 Kings', 15, 32, '&nbsp;د اِسرائيل بادشاه د رملياه زوئ فقح د بادشاهۍ په دوېم کال، د عُزياه زوئ يوتام د يهوداه بادشاه جوړ شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9394, '2 Kings 15:33', '2 Kings', 15, 33, '&nbsp;چې عُمر يې پينځويشت کاله وو، هغۀ په يروشلم کښې شپاړس کاله بادشاهى وکړه. د هغۀ مور يروسا د صدوق لور وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9395, '2 Kings 15:34', '2 Kings', 15, 34, '&nbsp;يوتام د خپل پلار عُزياه په مِثالونو عمل وکړو او هغه کار يې کولو چې مالِک خُدائ پرې رضا کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9396, '2 Kings 15:35', '2 Kings', 15, 35, '&nbsp;خو علاقائى عبادتخانې نۀ وې تباه شوى او خلقو هلته قربانۍ پېش کولې او خوشبوئى يې سوزولې. يوتام د مالِک خُدائ د کور شمالى طرف ته دروازه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9397, '2 Kings 15:36', '2 Kings', 15, 36, '&nbsp;يوتام چې نور څۀ هم کړى دى هغه د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9398, '2 Kings 15:37', '2 Kings', 15, 37, '&nbsp;د هغۀ د بادشاهۍ په دوران کښې مالِک خُدائ وړومبے د شام بادشاه رضين او د اِسرائيل بادشاه فقح ورولېږل چې په يهوداه باندې حمله وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9399, '2 Kings 15:38', '2 Kings', 15, 38, '&nbsp;يوتام مړ شو او د داؤد په ښار کښې په شاهى اديره کښې ښخ شو او د هغۀ زوئ احاز د هغۀ نه پس بادشاه جوړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(9400, '2 Kings 16:1', '2 Kings', 16, 1, '&nbsp;د اِسرائيل بادشاه د رملياه زوئ فقح د بادشاهۍ په اوولسم کال، د يوتام زوئ احاز د يهوداه بادشاه شو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');